pub proof fn always_and_equality<T>(p: TempPred<T>, q: TempPred<T>)
    ensures always(p.and(q)) == always(p).and(always(q)),
{
    let left = always(p.and(q));
    let ap = always(p);
    let aq = always(q);
    let right = ap.and(aq);

    // left.entails(right)
    assert(left.entails(right)) by {
        forall |ex: Execution<T>| {
            if left.satisfied_by(ex) {
                // Prove ap.satisfied_by(ex)
                assert(ap.satisfied_by(ex)) by {
                    forall |i: nat| {
                        // From left.satisfied_by(ex) we know (p.and(q)).satisfied_by(ex.suffix(i))
                        assert(#[trigger] p.and(q).satisfied_by(ex.suffix(i)));
                        assert(p.satisfied_by(ex.suffix(i)));
                    }
                };

                // Prove aq.satisfied_by(ex)
                assert(aq.satisfied_by(ex)) by {
                    forall |i: nat| {
                        assert(#[trigger] p.and(q).satisfied_by(ex.suffix(i)));
                        assert(q.satisfied_by(ex.suffix(i)));
                    }
                };

                assert(right.satisfied_by(ex));
            }
        }
    };

    // right.entails(left)
    assert(right.entails(left)) by {
        forall |ex: Execution<T>| {
            if right.satisfied_by(ex) {
                // right.satisfied_by(ex) gives ap.satisfied_by(ex) and aq.satisfied_by(ex)
                assert(ap.satisfied_by(ex));
                assert(aq.satisfied_by(ex));

                // Show left.satisfied_by(ex)
                assert(left.satisfied_by(ex)) by {
                    forall |i: nat| {
                        assert(#[trigger] p.satisfied_by(ex.suffix(i)));
                        assert(#[trigger] q.satisfied_by(ex.suffix(i)));
                        assert(p.and(q).satisfied_by(ex.suffix(i)));
                    }
                };
            }
        }
    };

    temp_pred_equality(left, right);
}

