    // right.entails(left)
    assert(right.entails(left)) by {
        assert forall |ex: Execution<T>| #[trigger] right.satisfied_by(ex) ==> left.satisfied_by(ex) by {
            if right.satisfied_by(ex) {
                assert(ap.satisfied_by(ex));
